Translate("deDE", "blasted-lands", {
	title = "Verwüstete Lande",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Verwüsteten Lande liegen am südlichen Ende der {link:eastern-kingdoms}Östlichen Königreiche{/link}, unterhalb der {link:swamp-of-sorrows}Sümpfe des Elends{/link}. Nichts Grünes wächst dort. Die Erde ist rot wie eine Wunde, und {link:razorfen-downs}die Hügel{/link} sind kahl. Der Himmel flackert von Blitzen, die keinen Regen bringen. Am südlichen Ende dieser Wüste steht das {link:dark-portal}Dunkle Portal{/link}, das Tor, durch das die orcische {link:horde}Horde{/link} zuerst in die Welt kam. Das Tor ist nun dunkel und still. Doch das Land um es herum ist nie genesen. {link:ogres}Oger{/link}, Dämonen und Kultisten haben es sich zu eigen gemacht, und eine einzige Festung der {link:alliance}Allianz{/link} hält Wache an der Straße.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Bevor die {link:orcs}Orcs{/link} kamen, war dieses Land der südliche Teil des Schwarzen Fenns, eines finsteren Moors, das sich von den Sümpfen nach Süden erstreckte. Dort öffneten der Hexenmeister {link:gul-dan}Gul'dan{/link} und der {link:the-night-watch}Wächter{/link} {link:medivh}Medivh{/link} ihr Tor zwischen den Welten, und die {link:horde}Horde{/link} marschierte aus dem Morast, um über das Königreich {link:kingdom-of-stormwind}Stormwind{/link} herzufallen. Die {link:fel-magic}Teufelsmagie{/link}, die das Portal errichtete, vergiftete das Moor um es herum. Als die {link:alliance}Allianz{/link} das Tor am Ende des {link:second-war}Zweiten Krieges{/link} zerstörte, erlitt das Land eine zweite Wunde. Das Wasser starb, das Schilf verdorrte, und der Boden verbrannte zu der Farbe, die er heute trägt. Die Leute der Königreiche gaben dem verwüsteten Land einen schlichten und bitteren Namen, und es hat diesen Namen seither behalten.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Portal ist seit vielen Jahren still, doch die Verwüsteten Lande sind es nicht mit ihm geworden. Nachdem die {link:burning-legion}Brennende Legion{/link} in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} gebrochen worden war, zog sich ein Rest ihres Heeres unter dem Verdammnislord {link:lord-kazzak}Kazzak{/link} in die faulende Narbe im Südwesten zurück. Sein Leutnant, der Dämon {link:razelikh-the-defiler}Razelikh der Entweiher{/link}, hat die Jahre seither damit verbracht, die übrigen Mächte des Landes an sich zu binden. Die Kultisten der Shadowsworn dienen ihm. Ebenso die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link}, deren Häuptling nun mehr Dämon als Oger ist. Einige der verlorenen Draenei wandern durch die Öde und suchen einen Weg nach Hause. Am nördlichen Rand von alledem steht {link:nethergarde-keep}Burg Nethergarde{/link}, wo die Magier der {link:kirin-tor}Kirin Tor{/link} und die Soldaten, die sie bewachen, das Portal erforschen und auf den Tag warten, an dem es erwacht. Die Straße zur Burg ist lang, und die Karawanen, die sie versorgen, kommen nicht immer an.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:the-night-watch}Wächter{/link} von {link:nethergarde-keep}Nethergarde{/link}.{/b} Magier, Kleriker, Soldaten und Bergleute halten die Burg und ihre Minen in den nördlichen Hügeln. Sie sind wenige, und sie sind weit von zu Hause.
• {b}Die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link}.{/b} Die Schreckensfels halten den Nordwesten der Öde und durchstreifen ihre Mitte. Ihre Hexenmeister und Ogermagier haben von ihrem dämonischen Herrn dunkle Künste gelernt.
• {b}Die Shadowsworn.{/b} Diese Kultisten halten die Höhlen der {link:serpent-s-coil}Schlangenschlinge{/link} und den Altar der Stürme im Westen. Sie sind die Erben des alten {link:shadow-council}Schattenrats{/link}, und sie dienen dem Entweiher.
• {b}Die {link:burning-legion}Brennende Legion{/link}.{/b} Verdammniswachen, Schreckenslords, Teufelswachen und Teufelshunde suchen die faulende Narbe und die Zugänge zum Dunklen Portal heim.
• {b}Die verlorenen Draenei.{/b} Elende Verbannte eines uralten Volkes wandern durch das Land. Manche sind wahnsinnig, und manche hoffen noch.
• {b}Die Tiere der Öde.{/b} Hyänen, Basilisken, Skorpoks, Geier und große Eber sind in der verseuchten Erde stark und seltsam geworden.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Schwarze Fenn.{/b} Keine Chronik erzählt, wie lange das Moor unberührt lag, bevor die {link:orcs}Orcs{/link} kamen. Es war abgelegen, nass und fast menschenleer.
• {b}Der Erste Krieg.{/b} Das Dunkle Portal öffnete sich im Sumpf, und die {link:horde}Horde{/link} errichtete dort ihre ersten Festungen. Aus dem Fenn marschierte sie nach Norden und Westen, um den {link:first-war}Ersten Krieg{/link} zu beginnen.
• {b}Der Zweite Krieg.{/b} Als die {link:alliance}Allianz von Lordaeron{/link} die Horde besiegt hatte, kamen ihre Soldaten nach Süden und zerstörten das Portal. Das Land um das Tor wurde durch die Zerstörung verbrannt und verzerrt.
• {b}{link:nethergarde-keep}Nethergarde{/link}.{/b} Auf Drängen des Erzmagiers {link:khadgar}Khadgar{/link} errichteten die {link:kirin-tor}Kirin Tor{/link} Burg Nethergarde an der einzigen Straße in die Öde. Die Könige der Allianz bezahlten ihre Mauern.
• {b}Das wiedergeöffnete Portal.{/b} Einige Jahre später flammte das Tor wieder auf. Orcs kamen von {red:draenor}Draenor{/red} hindurch und belagerten Nethergarde. Die Allianz schickte ihnen ein Heer durch das Portal hinterher, und das Tor wurde ein zweites Mal zerstört. Die Expedition kehrte nicht zurück.
• {b}Die Gegenwart.{/b} Seither steht das Portal kalt. Der Rest der Legion kam nach dem {link:third-war}Dritten Krieg{/link} in die faulende Narbe, und ein Regiment der Horde, das in die Öde marschierte, um sie auszukundschaften, ging fast bis auf den letzten Mann verloren.]=],
		},
		{
			title = "Überlieferungen der Öde",
			text = [=[• Man sagt, dass nie ein Regen den Boden der Verwüsteten Lande erreicht hat. Die Stürme, die über den östlichen Hügeln losbrechen, fließen ins Meer ab, bevor der rote Lehm trinken kann.
• Die Tiere der Öde gleichen ihren Verwandten anderswo nicht. Zwei elfische Blutmagier an der Nordgrenze sind überzeugt, dass die Energien, die das Portal freisetzte, sie zur Veränderung zwangen, und sie zahlen gut für den Beweis.
• Reisende, die die Südgrenze des Sumpfes erreichen, begegnen manchmal dem Geist eines {link:orcs}Orcs{/link}, der neben der Straße steht. Er warnt sie umzukehren. Er weiß, was dahinter wartet.
• Ein großer schwarzer Drache namens Teremus der Verschlinger soll über dem Dunklen Portal kreisen. Die {link:the-night-watch}Wächter{/link} von {link:nethergarde-keep}Nethergarde{/link} zählen die Patrouillen, die er geholt hat.
• Tief in der faulenden Narbe, fern jeder Straße, hütet ein alter menschlicher Hexenmeister namens {link:daio-the-decrepit}Daio{/link} einen Altar unter den Dämonen. Er ist nicht ihr Gefangener.]=],
		},
	},
})

Translate("deDE", "nethergarde-keep", {
	title = "Burg Nethergarde",
	aliases = { "Nethergarde", "Festung Nethergarde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Nethergarde steht auf einer hohen Klippe im Nordosten der Verwüsteten Lande, über der einzigen Straße in die Öde. Die {link:kirin-tor}Kirin Tor{/link} errichteten sie nach dem {link:second-war}Zweiten Krieg{/link}, um das zerbrochene {link:dark-portal}Dunkle Portal{/link} zu beobachten, und die Könige der {link:alliance}Allianz{/link} bezahlten ihre Steine. Ihr Gründer, der Erzmagier {link:khadgar}Khadgar{/link}, ging vor langer Zeit durch das Portal und kehrte nicht zurück. Die Burg hat ihre Wacht ohne ihn gehalten.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Nethergarde ist ein düsterer und geschäftiger Ort. Ihre Analytiker und Risswächter erforschen das Portal vom Magierturm aus. Ihre Kleriker pflegen die Verwundeten, und ihre Soldaten halten die Mauern gegen die Überfälle der {link:dreadmaul-rock}Schreckensfels{/link}. Ihre Bergleute graben in den Hügeln hinter ihr. Alles andere muss über die lange Straße von {link:stormwind-city}Stormwind{/link} durch {link:darkshire}Dunkelhain{/link} und den Sumpf kommen. Unterwegs gehen Karawanen an {link:ogres}Oger{/link} und Tiere verloren, und der Rüstmeister zählt jede Kiste, die ihn erreicht. Die Burg ist auch ein Ort der Begegnungen. Ein Wahrsager der Wildhammer arbeitet in ihrem Turm, und ein elfischer Gesandter vertritt in ihrer Halle die Ansicht, dass die {link:alliance}Allianz{/link} den falschen Feind bekämpft.]=],
		},
	},
})

Translate("deDE", "garrison-armory", {
	title = "Garnison-Waffenkammer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Garnison-Waffenkammer liegt in den Hügeln hinter {link:nethergarde-keep}Burg Nethergarde{/link}, wo die Garnison der {link:kirin-tor}Kirin Tor{/link} Minen im roten Fels angelegt hat. Bergleute aus Nethergarde arbeiten in ihren Stollen unter den Augen von Vorarbeitern und Ingenieuren. Das Erz, das sie heraufholen, ist eines der wenigen Dinge, die die Verwüsteten Lande freiwillig hergeben. Es schmiedet die Waffen der Burg und bezahlt einen Teil der Waren, die über die Straße aus dem Norden kommen müssen. Es ist harte Arbeit an einem harten Ort, und die Bergleute wissen, dass die Soldaten auf den Mauern über ihnen alles sind, was zwischen den Schächten und den Ogern der Öde steht.]=],
		},
	},
})

Translate("deDE", "dreadmaul-hold", {
	title = "Feste Schreckensfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Feste Schreckensfels ist die Hochburg der {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link} im Nordwesten der Verwüsteten Lande, nahe dem Pass, der aus dem Sumpf herabführt. Ihre Rohlinge und Ogermagier überfallen die Straße nach {link:nethergarde-keep}Nethergarde{/link}, und sie haben die nördliche Öde für jede Karawane gefährlich gemacht. Ihr Herr ist {link:grol-the-destroyer}Grol der Zerstörer{/link}. Einst war er ein Ogerhäuptling wie jeder andere, doch er verkaufte sich dem Dämon {link:razelikh-the-defiler}Razelikh{/link} für Unsterblichkeit, und er ist kein Oger mehr. In der Feste stehen drei versklavte Soldaten eines verlorenen Regiments der {link:horde}Horde{/link}, an seinen Dienst gebunden. Sie können nicht sterben, und sie können nicht gehen.]=],
		},
	},
})

Translate("deDE", "dreadmaul-post", {
	title = "Schreckensfelsposten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schreckensfelsposten ist ein Ogerlager im Herzen der Verwüsteten Lande, südlich der {link:rise-of-the-defiler}Anhöhe des Entweihers{/link}. Die {link:dreadmaul-rock}Schreckensfels{/link}, die ihn halten, sind die gefährlichsten ihres Stammes: große Zermalmer und Ogerhexenmeister, die gelernt haben, Teufelsmacht anzurufen. Sie bewachen die Mitte der Öde und den Weg zum Dunklen Portal. Die Schreckensfels kamen im Gefolge der {link:orcs}Orcs{/link} in diese Lande, und sie gingen nie wieder. Ihre Ogermagier und Hexenmeister sind der Beweis, dass die Dämonen der faulenden Narbe in ihnen willige Schüler gefunden haben.]=],
		},
	},
})

Translate("deDE", "serpent-s-coil", {
	title = "Schlangenschlinge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlangenschlinge ist ein gewundenes Labyrinth aus Höhlen im Osten der Verwüsteten Lande. Ausgebrannte Hüllen orcischer Gebäude stehen vor ihren Eingängen, Überbleibsel aus den Kriegen. Die Kultisten der Shadowsworn haben sie zu ihrem Unterschlupf gemacht, und {link:archmage-allistarj}Erzmagier Allistarj{/link} befehligt sie von innen. Hier wurden die Soldaten eines verlorenen Regiments der {link:horde}Horde{/link} gefoltert, und hier wurde ihr {link:kirith-the-damned}Leutnant Kirith{/link} gebrochen. In der tiefsten Höhle streift nun eine monströse Teufelsbestie umher. Sie war einst ein Mann, und sie hat noch immer einen Namen.]=],
		},
	},
})

Translate("deDE", "rise-of-the-defiler", {
	title = "Anhöhe des Entweihers",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Anhöhe des Entweihers ist der höchste Berg der Verwüsteten Lande, ein Felsen aus rotem Stein nahe der Mitte der Öde. Sein Gipfel ist der Hort von {link:razelikh-the-defiler}Razelikh{/link} dem Entweiher, dem Dämonenfürsten des Landes. Kein Pfad führt hinauf. Runen, die nahe dem Fuß des Berges eingeritzt sind, können einen zum Hort tragen, doch nur den, der das eigene Amulett des Entweihers besitzt. Am Fuß der Anhöhe wartet ein Schemen, der {link:deathly-usher}Deathly Usher{/link}, für immer an diese Welt gebunden. Auf dem Gipfel steht der Altar des Entweihers, an dem der Dämon herbeigerufen werden kann.]=],
		},
	},
})

Translate("deDE", "the-tainted-scar", {
	title = "Die faulende Narbe",
	aliases = { "Faulende Narbe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die faulende Narbe ist ein breiter Riss aus totem Boden im Südwesten der Verwüsteten Lande. Einst war sie ein Teil des Schwarzen Fenns. Nun ist sie die letzte Hochburg der {link:burning-legion}Brennenden Legion{/link} in diesen Landen. Nach der Niederlage am {link:battle-of-mount-hyjal}Berg Hyjal{/link} zog sich der Verdammnislord {link:lord-kazzak}Kazzak{/link} mit dem, was von seinem Heer übrig war, hierher zurück, und hier ist er geblieben. Kommandanten der Verdammniswache, Schreckenslords, Teufelswachen und Manahunde füllen die Narbe. Kein Heer der Königreiche hat versucht, sie zurückzuerobern.]=],
		},
		{
			title = "Der Altar des Hexenmeisters",
			text = [=[Am nördlichen Rand der Narbe steht ein Altar, an dem ein alter menschlicher Hexenmeister, {link:daio-the-decrepit}Daio der Altersschwache{/link}, unter den Dämonen seine Heimat gefunden hat. Wer ihn aufsucht, kommt, um zu lernen, wie ein Dämon der Verdammniswache gebunden werden kann.]=],
		},
	},
})

Translate("deDE", "lord-kazzak", {
	title = "Lord Kazzak",
	subtitle = "Befehlshaber des Rests der Legion",
	found = "Die faulende Narbe, im Südwesten der Verwüsteten Lande",
	hint = [=[Sucht den Dämonenfürsten, der die faulende Narbe befehligt. Geht nicht allein.]=],
	allegiance = "Brennende Legion",
	aliases = { "Kazzak" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Kazzak ist ein Verdammnislord der {link:burning-legion}Brennenden Legion{/link}, ein turmhoher Dämon, der befehligt, was vom Heer der Legion in den {link:eastern-kingdoms}Östlichen Königreichen{/link} übrig ist. Er hält die faulende Narbe im Südwesten der Verwüsteten Lande. Verdammniswachen, Schreckenslords und Teufelswachen dienen ihm dort.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Als {link:archimonde}Archimonde{/link} am {link:battle-of-mount-hyjal}Berg Hyjal{/link} fiel, wurden die Heere der Legion auf {link:azeroth}Azeroth{/link} gebrochen. Kazzaks Heer ging nicht zugrunde. Es fiel in die faulende Narbe zurück, nahe dem stillen {link:dark-portal}Dunklen Portal{/link}, und dort ist es geblieben. Von allen Dämonen, die in der Welt verblieben sind, sind nur wenige so mächtig. Von der Narbe aus setzte er seinen grimmigsten Leutnant, {link:razelikh-the-defiler}Razelikh{/link} den Entweiher, ein, um den Rest der Öde unter den Schatten der Legion zu bringen. Die {link:the-night-watch}Wächter{/link} von {link:nethergarde-keep}Nethergarde{/link} glauben, dass auch die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link} ihm dienen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte den Rest der Legion nach der Niederlage am {link:mount-hyjal}Berg Hyjal{/link} in die faulende Narbe.
• Er beauftragte {link:razelikh-the-defiler}Razelikh{/link} den Entweiher, die Verwüsteten Lande zu sichern.
• Er hält die Narbe bis heute mit einem Heer aus Verdammniswachen, Schreckenslords und Teufelswachen.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik der Königreiche verzeichnet, wann Kazzak zuerst nach {link:azeroth}Azeroth{/link} kam oder was er sucht, indem er so nahe am Dunklen Portal verweilt. Die Magier von {link:nethergarde-keep}Nethergarde{/link} haben ihre Befürchtungen, doch sie sprechen sie nicht laut aus.]=],
		},
	},
	chapters = {
		{
			title = "Der Herr des Entweihers",
			hint = "Erfahrt vom Dämonenjäger aus Azshara, wem Razelikh dient.",
			text = [=[Der Dämonenjäger {link:loramus-thalipedes}Loramus Thalipedes{/link} erzählte die Geschichte ohne Umschweife. Im Zeitalter des Krieges war {link:razelikh-the-defiler}Razelikh{/link} der gefürchtetste von Kazzaks Leutnants gewesen. Als die Legion geschlagen und Kazzak in die faulende Narbe getrieben wurde, war es Razelikh, der ausgesandt wurde, um das Land für ihn zu halten. Jeder {link:ogres}Oger{/link} und jeder Kultist, der dem Entweiher dient, dient am Ende dem Verdammnislord in der Narbe.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:loramus-thalipedes}Loramus{/link}, die Geschichte des Entweihers]=],
		},
	},
	bonds = {
		{ id = "razelikh-the-defiler", name = "Razelikh der Entweiher", note = "sein Leutnant" },
		{ id = "archimonde", name = "Archimonde", note = "sein gefallener Befehlshaber" },
	},
})

Translate("deDE", "razelikh-the-defiler", {
	title = "Razelikh der Entweiher",
	subtitle = "Dämonenfürst der Verwüsteten Lande",
	found = [=[Auf der Anhöhe des Entweihers, wenn er mit seinem eigenen Amulett gerufen wird]=],
	hint = [=[Nur wer das Amulett des Entweihers besitzt, kann zu seinem Hort hinaufsteigen.]=],
	allegiance = "Brennende Legion",
	aliases = { "Razelikh", "der Entweiher", "Rakh'likh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Razelikh der Entweiher ist ein Schreckenslord der {link:burning-legion}Brennenden Legion{/link} und der wahre Herr der Verwüsteten Lande. Einst war er der gefürchtetste Leutnant von {link:lord-kazzak}Lord Kazzak{/link}. Nun beherrscht er die Öde von einem Hort auf dem höchsten Berg des Landes aus, und die {link:ogres}Oger{/link} und Kultisten der Gegend dienen ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Als die Legion besiegt war und {link:lord-kazzak}Kazzak{/link} sich in die faulende Narbe zurückzog, wurde Razelikh ausgesandt, um das Land zu sichern. Er tat es eher mit List als mit Gewalt. Während die {link:alliance}Allianz{/link} und die {link:horde}Horde{/link} um Lande weit im Norden stritten, führte er die verstreuten Sekten des {link:shadow-council}Schattenrats{/link} und die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link} zusammen. Der Preis, den er bot, war Macht. Er schuf ein Amulett, brach es in drei Teile und gab je ein Stück an {link:archmage-allistarj}Erzmagier Allistarj{/link}, {link:lady-sevine}Lady Sevine{/link} und {link:grol-the-destroyer}Grol{/link} den Zerstörer. Jedes Stück machte seinen Träger innerhalb der Verwüsteten Lande unsterblich. Jedes band seinen Träger auch für immer an seinen Dienst. Seine drei Hauptleute verstanden die zweite Gabe erst, als es zu spät war.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sicherte die Verwüsteten Lande nach der Niederlage der Legion für {link:lord-kazzak}Kazzak{/link}.
• Er vereinte die Kultisten der Shadowsworn und die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link} unter seinem Befehl.
• Er nahm ein Regiment der {link:horde}Horde{/link} gefangen und machte die Seelen seiner Soldaten zu todlosen Sklaven.
• Er band drei Hauptleute mit den Stücken seines Amuletts an sich.]=],
		},
	},
	chapters = {
		{
			title = "Das Regiment",
			hint = [=[Hört die Geschichte des gefallenen Helden der Horde am Rand des Sumpfes.]=],
			text = [=[Der Geist an der Grenze des Sumpfes war einst Trebor, ein Befehlshaber der {link:horde}Horde{/link}. Er führte ein Regiment in die Öde, und die Diener des Entweihers nahmen es gefangen. Razelikh riss den gefangenen Soldaten die Seelen heraus und band ihre Körper an Steine. Neun behielt er für sich, gebunden nahe dem Dunklen Portal. Die anderen neun teilte er unter seinen Hauptleuten auf, je drei. Ohne ihre Seelen können die Männer nicht sterben. Ihre Gefangennahme, sagte der Dämonenjäger {link:loramus-thalipedes}Loramus{/link}, besiegelte den Pakt zwischen dem Dämon, den Kultisten und den Ogern.]=],
		},
		{
			title = "Die Steine der Bindung",
			hint = "Befreit die gebundenen Soldaten des verlorenen Regiments.",
			text = [=[{link:kirith-the-damned}Kirith{/link} hatte die Schwäche gefunden, bevor er verloren ging. Jeder gebundene Soldat konnte bis an den Rand der Auflösung geschlagen werden, und allein in diesem Augenblick konnte sein Bindungsstein zerschmettert werden. Achtzehn Steine wurden überall in den Verwüsteten Landen zerbrochen, nahe dem Portal und in den Höhlen der drei Hauptleute. Die Soldaten des Regiments wurden befreit, um endlich zu ruhen. Razelikh verlor seine unsterblichen Wachen, und er erfuhr, dass jemand Jagd auf ihn machte.]=],
		},
		{
			title = "Das zerbrochene Amulett",
			hint = "Zerschlagt die Triade und macht das Amulett wieder ganz.",
			text = [=[Keine gewöhnliche Klinge konnte den drei Hauptleuten schaden. Der Dämonenjäger {link:loramus-thalipedes}Loramus Thalipedes{/link} kannte den wahren Namen des Entweihers, und mit dem Schmied {link:galvan-the-ancient}Galvan{/link} dem Uralten half er, Waffen aus Azsharit zu schmieden, die diesen Namen trugen. Mit diesen Waffen wurden {link:grol-the-destroyer}Grol{/link}, {link:lady-sevine}Sevine{/link} und {link:archmage-allistarj}Allistarj{/link} zu Fall gebracht, und ihre drei Stücke des Amuletts wurden wieder vereint. Der Entweiher spürte den Bruch in seiner Befehlskette. Er wusste, dass er gejagt wurde.]=],
		},
		{
			title = "Ihr seid Rakh'likh",
			hint = "Benutzt das Amulett am Altar des Entweihers.",
			text = [=[Das Amulett öffnete den Weg zum Gipfel. Am Altar des Entweihers wurde der Dämon herbeigerufen. Er rief seine Diener herbei, Ilifar den Seelenhüter und Felcular, seinen Champion, und er kämpfte am Rand des Berges. Er fiel. Eines seiner Hörner wurde vom Berg herabgebracht, als Beweis, dass der dämonische Herr der Verwüsteten Lande geschlagen werden konnte. Der Schutz, den er geschmiedet hatte, wurde Trebor gegeben, um ihn zu zerstören, damit niemand ihn je wieder benutzen konnte.]=],
		},
	},
	mentions = {
		{
			text = [=[Kleinliche Zankereien, der Weg der {link:alliance}Allianz{/link} zum gefallenen Helden]=],
		},
		{
			text = [=[Tiefer Fall, der Weg der {link:horde}Horde{/link} zum gefallenen Helden]=],
		},
		{ text = "Der Schutz der Dunkelheit, das Geheimnis der Triade" },
		{ text = "Der Dämonenjäger" },
		{ text = "Rückkehr in die Verwüsteten Lande" },
	},
	bonds = {
		{ id = "lord-kazzak", name = "Lord Kazzak", note = "sein Herr" },
		{ id = "grol-the-destroyer", name = "Grol der Zerstörer", note = "gebundener Hauptmann" },
		{ id = "archmage-allistarj", name = "Erzmagier Allistarj", note = "gebundener Hauptmann" },
		{ id = "lady-sevine", name = "Lady Sevine", note = "gebundene Hauptfrau" },
		{ id = "fallen-hero-of-the-horde", name = "Gefallener Held der Horde", note = "sein Gefangener und sein Feind" },
