	},
})

Translate("deDE", "grol-the-destroyer", {
	title = "Grol der Zerstörer",
	subtitle = "Herr der Schreckensfels",
	found = "Feste Schreckensfels, im Nordwesten der Verwüsteten Lande",
	hint = "Sucht den Herrn der Oger in ihrer nördlichen Feste.",
	allegiance = "Schreckensfels · Razelikh der Entweiher",
	aliases = { "Grol" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grol der Zerstörer beherrscht die {link:ogres}Oger{/link} der {link:dreadmaul-rock}Schreckensfels{/link} von der {link:dreadmaul-hold}Feste Schreckensfels{/link} aus. Einst war er ein Ogerhäuptling. Er nahm ein Drittel von Razelikhs Amulett im Tausch gegen Macht und endloses Leben, und die Gabe des Dämons formte ihn zu etwas um, das einem Dämon näher ist. Keine gewöhnliche Waffe kann ihn töten, solange er in den Verwüsteten Landen bleibt. Drei Soldaten des verlorenen Regiments der {link:horde}Horde{/link} wurden ihm als Sklaven gegeben.]=],
		},
	},
	chapters = {
		{
			title = "Das Amulett von Grol",
			hint = [=[Bringt den Herrn der Schreckensfels mit einer Klinge zu Fall, die den Namen des Entweihers trägt.]=],
			text = [=[Grol war der Erste der Triade, der erfuhr, dass Unsterblichkeit ihren Preis hat. Die Waffe, im eigenen Namen des Entweihers geschmiedet, brach seinen Schutz, und sein Stück des Amuletts wurde seinem Leib abgenommen.]=],
		},
	},
})

Translate("deDE", "archmage-allistarj", {
	title = "Erzmagier Allistarj",
	subtitle = "Erzmagier der Shadowsworn",
	found = "In der Schlangenschlinge",
	hint = [=[Sucht den Erzmagier, der über die Kultisten der östlichen Höhlen herrscht.]=],
	allegiance = "Shadowsworn · Razelikh der Entweiher",
	aliases = { "Allistarj" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzmagier Allistarj führt die Kultisten der Shadowsworn in der {link:serpent-s-coil}Schlangenschlinge{/link}. Er ist einer der drei, die ein Stück von Razelikhs Amulett nahmen, und er ist durch es an den Entweiher gebunden. Er war der Folterknecht des verlorenen Regiments der {link:horde}Horde{/link}. In seinen Höhlen wurden Trebor und sein {link:kirith-the-damned}Leutnant Kirith{/link} abwechselnd gequält, jeder gezwungen, dem anderen zuzusehen, und es waren Allistarjs Experimente, die Kiriths Seele brachen. Drei der Soldaten des Regiments dienen ihm noch immer.]=],
		},
	},
	chapters = {
		{
			title = "Das Amulett von Allistarj",
			hint = [=[Stellt Euch dem Erzmagier in der Schlangenschlinge mit dem Fluch des Entweihers.]=],
			text = [=[Der Erzmagier hatte seine Seele für die Macht verkauft, andere zu quälen. Als er fiel, wurde ihm sein Drittel des Amuletts abgenommen.]=],
		},
	},
})

Translate("deDE", "lady-sevine", {
	title = "Lady Sevine",
	subtitle = "Hexenmeisterin der Shadowsworn",
	found = [=[Der Altar der Stürme, am westlichen Rand der Verwüsteten Lande]=],
	hint = [=[Sucht die Hexenmeisterin, die in den westlichen Hügeln einen Altar hütet.]=],
	allegiance = "Shadowsworn · Razelikh der Entweiher",
	aliases = { "Sevine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lady Sevine ist eine Hexenmeisterin der Shadowsworn und eine der drei Hauptleute, die an {link:razelikh-the-defiler}Razelikh{/link} den Entweiher gebunden sind. Sie hält den Altar der Stürme am westlichen Rand der Öde, wo ihre Kultisten ihre Riten zwischen den Vollstreckern und Schreckensweberinnen der Sekte vollziehen. Wie ihre Gefährten trägt sie ein Drittel des Amuletts des Entweihers, und wie sie kann sie in diesen Landen mit gewöhnlichen Mitteln nicht erschlagen werden. Drei Soldaten des verlorenen Regiments der {link:horde}Horde{/link} sind an ihren Dienst gebunden.]=],
		},
	},
	chapters = {
		{
			title = "Das Amulett von Sevine",
			hint = [=[Steigt mit dem Fluch des Entweihers zum Altar der Stürme hinauf.]=],
			text = [=[Sevine hatte ihren Altar errichtet, um die Stürme der Öde anzurufen. Er rettete sie nicht. Ihr Stück des Amuletts war das letzte der drei.]=],
		},
	},
})

Translate("deDE", "kirith-the-damned", {
	title = "Kirith der Verdammte",
	subtitle = "Der gebrochene Leutnant",
	found = "Die tiefste Höhle der Schlangenschlinge",
	hint = [=[Findet heraus, was aus dem Leutnant wurde, der nie aus den Höhlen herauskam.]=],
	allegiance = "Horde (einst)",
	aliases = { "Kirith", "Leutnant Kirith" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kirith war der Leutnant von Trebor, dem Befehlshaber eines Regiments der {link:horde}Horde{/link}, das in den Verwüsteten Landen verloren ging. Er und sein Befehlshaber wurden Seite an Seite von {link:archmage-allistarj}Erzmagier Allistarj{/link} gefoltert. In einer Pause ihrer Qualen war es Kirith, der erfuhr, wie die gebundenen Soldaten des Regiments befreit werden könnten. Sein eigener Wille gab schließlich nach. Die Experimente verzerrten seine Seele zu einer Teufelsbestie, die den hinteren Teil der {link:serpent-s-coil}Schlangenschlinge{/link} heimsucht.]=],
		},
	},
	chapters = {
		{
			title = "Der Geist von Kirith",
			hint = "Befreit den Leutnant von der Bestie, zu der er wurde.",
			text = [=[Als die Bestie erschlagen war, erhob sich Kiriths Geist aus ihr. Er hatte wenig Zeit, und er verschwendete sie nicht. Er erzählte von der Triade und von dem Amulett, das sich die drei Hauptleute teilten, dem einzigen Schlüssel, der den Entweiher herbeirufen konnte. Dann schickte er seine Retter zurück zu seinem Befehlshaber.]=],
		},
	},
})

Translate("deDE", "deathly-usher", {
	title = "Deathly Usher",
	subtitle = "Hüter der Treppe des Entweihers",
	found = "Am Fuß der Anhöhe des Entweihers",
	hint = [=[Sprecht mit dem Schemen, der unterhalb des Berges des Entweihers wartet.]=],
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Deathly Usher ist ein Schemen, der am Fuß der {link:rise-of-the-defiler}Anhöhe des Entweihers{/link} wartet. Er sagt, dass er für immer an diese Welt gebunden ist, und er fragt, was die Lebenden von ihm wollen. Denen, die das Amulett des Entweihers tragen, öffnet er den Weg zum Gipfel, wo {link:razelikh-the-defiler}Razelikh{/link} seinen Hort hat. Was der Usher im Leben war und wer ihn hier gebunden hat, sagt er nicht.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik nennt den Usher beim Namen oder erzählt, wie er dazu kam, dem Berg zu dienen.]=],
		},
	},
	mentions = {
		{
			text = [=[Ihr seid {link:razelikh-the-defiler}Rakh'likh{/link}, Dämon, der Weg zum Hort]=],
		},
	},
})

Translate("deDE", "quartermaster-lungertz", {
	title = "Rüstmeister Lungertz",
	subtitle = "Rüstmeister von Nethergarde",
	found = "Burg Nethergarde",
	hint = [=[Sprecht mit dem Mann, der jede Kiste zählt, die Nethergarde erreicht.]=],
	allegiance = "Burg Nethergarde · Kirin Tor",
	aliases = { "Lungertz" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rüstmeister Lungertz verwaltet die Vorräte von {link:nethergarde-keep}Burg Nethergarde{/link}. Er ist die Lebensader der Burg zu den Königreichen. Nahrung, Waffen, Machtsteine und die Reagenzien, die ihre Magier brauchen, müssen alle über die lange Straße von {link:stormwind-city}Stormwind{/link} kommen, und er steht für alles ein. Zu viel davon kommt nie an. {link:ogres}Oger{/link} überfallen die Karawanen im Sumpf, und Wagen gehen zwischen {link:darkshire}Dunkelhain{/link} und der Burg verloren. Er begrüßt jede Lieferung, als wäre sie ein kleines Wunder, und manchmal ist sie das.]=],
		},
	},
	chapters = {
		{
			title = "Die Straße nach Nethergarde",
			hint = "Bringt Vorräte über die lange Straße zur Burg.",
			text = [=[Machtsteine aus {link:darkshire}Dunkelhain{/link}, die ihre Ladung verloren hätten, hätten sie auf die nächste Karawane gewartet. Ein Fass mit seinem Namen darauf, weit abseits der Straße gefunden. Eine letzte Kiste, gerettet aus der zerstörten Karawane von {link:watcher-biggs}Wächter Biggs{/link}, die die Burg mitsamt ihrem Fuhrmann verloren gegeben hatte. Jede erreichte ihn durch die Hand eines Reisenden, und jede erzählte dieselbe Geschichte. {link:nethergarde-keep}Nethergarde{/link} geht alles aus, vor allem die Azorankristalle, ohne die ihre Magier nicht auskommen.]=],
		},
	},
	mentions = {
		{ text = "Vorräte für {link:nethergarde-keep}Nethergarde{/link}" },
		{ text = "Die verlorenen Vorräte" },
		{ text = "Liefert die Ladung ab" },
	},
})

Translate("deDE", "watcher-mahar-ba", {
	title = "Wächter Mahar Ba",
	subtitle = "Gelehrter von Nethergarde",
	found = "Burg Nethergarde",
	hint = [=[Sprecht mit dem Wächter, der die Schriften Khadgars studiert.]=],
	allegiance = "Burg Nethergarde · Kirin Tor",
	aliases = { "Mahar Ba" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wächter Mahar Ba ist einer der Gelehrten von {link:nethergarde-keep}Burg Nethergarde{/link}. Seine Arbeit ist die Erforschung des {link:dark-portal}Dunklen Portals{/link} und der Kräfte, die es schufen, und er hat lange gehofft, die Gedanken des Gründers der Burg zu diesem Thema zu lesen. Er ließ in {link:stormwind-city}Stormwind{/link} nach einer Abschrift von {link:khadgar}Khadgar{/link}s Abhandlungen über das Zusammentreffen der Welten schicken, und er wartete lange darauf.]=],
		},
	},
	chapters = {
		{
			title = "Mazens Auftrag",
			hint = [=[Holt die Abhandlung zurück, die auf der Straße durch den Sumpf verloren ging.]=],
			text = [=[Die Abhandlung wurde von Meister Mazen von Stormwinds Akademie der arkanen Künste geschickt, in den Händen einer jungen Akolythin. Sie verlor sie in den Sümpfen des Elends, auf der Flucht vor den wandelnden Pflanzen des Moors. Als sie endlich {link:nethergarde-keep}Nethergarde{/link} erreichte, konnte Mahar Ba kaum erwarten zu beginnen. Einen Blick in Khadgars Geist zu werfen, sagte er, sei eine Freude über alle Maßen.]=],
		},
	},
	mentions = {
		{ text = "Mazens Auftrag" },
	},
})

Translate("deDE", "thadius-grimshade", {
	title = "Thadius Grimshade",
	subtitle = "Wahrsager von Nethergarde",
	found = "Der Magierturm von Burg Nethergarde",
	hint = "Sucht den Wahrsager der Wildhammer im Turm von Nethergarde.",
	allegiance = "Wildhammerklan",
	aliases = { "Grimshade" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thadius Grimshade ist ein {link:dwarves}Zwerg{/link} der Wildhammer und ein Wahrsager. Er verließ {link:aerie-peak}Aerie Peak{/link} vor Jahren auf der Suche nach dunklerem Wissen, und im Magierturm von {link:nethergarde-keep}Nethergarde{/link} hat er einen Platz dafür gefunden. Sein alter Klan hat ihn nicht vergessen, und er hat sie nicht vergessen. Er setzt seine Künste noch immer für die Wildhammer ein, wenn auch nie umsonst.]=],
		},
	},
	chapters = {
		{
			title = "Die Weissagung",
			hint = [=[Bringt dem Wahrsager die Feder eines Greifen und zahlt seinen Preis.]=],
			text = [=[Die Greifenmeister von {link:aerie-peak}Aerie Peak{/link} schickten ihm eine Feder aus dem Nest von Sharpbeak, einem jungen Greifen, der gestohlen worden war. Grimshade verlangte zuerst einen Preis: das Medaillon des Trolls Nekrum Gutchewer aus {red:zul-farrak}Zul'Farrak{/red}, das seinem Besitzer ein unnatürlich langes Leben verliehen hatte. Er hoffte, sein Geheimnis ohne seinen Fluch zu ergründen. Als das Medaillon sein war, wirkte er seine Weissagung, folgte dem Faden von der Feder zum Greifen und fand Sharpbeak als Gefangenen in einer Trollstadt im {link:the-hinterlands}Hinterland{/link}.]=],
		},
	},
	mentions = {
		{ text = "Nekrums Medaillon" },
		{ text = "Rückkehr ins {link:the-hinterlands}Hinterland{/link}" },
	},
})

Translate("deDE", "ambassador-ardalan", {
	title = "Botschafter Ardalan",
	subtitle = "Gesandter in Nethergarde",
	found = "Burg Nethergarde",
	hint = [=[Sprecht mit dem Gesandten, der für ein unwahrscheinliches Bündnis eintritt.]=],
