	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Enohar Thunderbrew ist eine Zwergin aus der Familie Thunderbrew, die die Garnison von {link:nethergarde-keep}Nethergarde{/link} mit Bier versorgt. Das Leben in der Burg ist steif und pflichtbewusst, und sie glaubt, dass ein Soldat manchmal einen Schluck braucht, um die Last der Wacht zu heben. Nachricht aus der Heimat erreicht sie noch immer über die Öde hinweg.]=],
