Translate("deDE", "kum-isha-the-collector", {
	title = "Kum'isha der Sammler",
	subtitle = "Sucher des Draenethysts",
	found = "In der Öde nahe der Anhöhe des Entweihers",
	hint = [=[Sucht den Verbannten, der im Herzen der Öde Kristalle sammelt.]=],
	allegiance = "Die verlorenen Draenei",
	aliases = { "Kum'isha" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kum'isha der Sammler ist einer der verlorenen Draenei, die durch die Verwüsteten Lande wandern, ein Verbannter eines uralten Volkes von einer Welt jenseits des {link:dark-portal}Dunklen Portals{/link}. Er hat ein Lager im Herzen der Öde und sammelt Draenethyst, einen Kristall seiner Heimat, der sich noch in der roten Erde finden lässt. Er glaubt, dass er mit genug davon einen Riss öffnen und sein Volk nach Hause führen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kum'isha ist verbittert, stolz und schnell mit der Zunge. {link:humans}Menschen{/link} und {link:orcs}Orcs{/link} beklagen sich jeweils über den Gestank des anderen, bemerkt er, doch für seine Nase riechen alle Völker dieser Welt gleich, und was er an ihnen riecht, ist Gier. Gier kostete ihn seine Heimat, sagt er, und Gier wird seine Rückkehr bezahlen. Er tauscht seine Schätze bereitwillig mit jenen, die ihm Kristalle bringen, und er verachtet sie dafür, dass sie den Handel annehmen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er durchsucht die Verwüsteten Lande nach Draenethyst, vor allem nach den seltenen makellosen Sphären.
• Er hat versucht, einen Riss zu seiner Heimat zu öffnen.
• Er bezahlt für jedes Kristallbruchstück, das ihm gebracht wird, und er verachtet jene, die es bringen.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik erzählt, wie Kum'isha und seine Gefährten in die Verwüsteten Lande kamen oder wie lange sie dort schon wandern.]=],
		},
	},
	chapters = {
		{
			title = "Die makellose Sphäre",
			hint = "Bringt dem Sammler den seltensten Kristall der Öde.",
			text = [=[Draenei hätten ganze Leben auf der Suche nach einer einzigen makellosen Sphäre aus Draenethyst verbracht, sagte Kum'isha, und seien gestorben, ohne ihre Suche zu beenden. Als ihm eine in die Hände gelegt wurde, konnte er es nicht glauben. Er versuchte sofort, ein Portal nach Hause zu beschwören. Der Versuch misslang. Er verlor die Hoffnung nicht. Er bat um eine weitere Sphäre.]=],
		},
		{
			title = "Des einen Draenei Plunder",
			hint = "Bringt dem Sammler die geringeren Bruchstücke des Kristalls.",
			text = [=[Die fehlerhaften Bruchstücke des Draenethysts werden nie einen Weg nach Hause öffnen. Doch Kum'isha nimmt sie, denn sie mögen seinem Volk auf andere Weise dienen, und er bezahlt sie mit den Schätzen dieser Welt, die er Plunder nennt. Er sagt jedem Verkäufer vielmals am Tag dieselben verächtlichen Worte. Er gibt zu, dass er diese Welt verabscheut.]=],
		},
	},
	mentions = {
		{ text = "Im Dienst von Kum'isha" },
		{ text = "Kum'ishas Bemühungen" },
		{ text = "In großen Mengen zählt alles" },
		{ text = "Des einen Draenei Plunder..." },
	},
})

Translate("deDE", "bloodmage-drazial", {
	title = "Blutmagier Drazial",
	subtitle = "Erforscher der Stärke der Tiere",
	found = "Gleich innerhalb der Nordgrenze der Verwüsteten Lande",
